<script setup>
import SourceBadge from './SourceBadge.vue'
import {computed,nextTick,ref,watch,onUnmounted} from 'vue'
import {useStudyActivity} from '../composables/useStudyActivity'
import {useLearning} from '../stores/learning'
import {questionMap,subjectMap,typeNames} from '../data/quiz'
import {correctText} from '../data/quiz/schema'
const props=defineProps({review:{type:Boolean,default:false}})
const emit=defineEmits(['choose','exit'])
const store=useLearning(),g=computed(()=>store.session(props.review))
const q=computed(()=>questionMap[g.value?.questionIds[g.value.index]])
const submitted=computed(()=>g.value?.answers[q.value?.id])
const count=computed(()=>Object.keys(g.value?.answers??{}).length)
const correct=computed(()=>Object.values(g.value?.answers??{}).filter(a=>a.correct).length)
const draft=computed({get:()=>g.value?.draft??'',set:v=>store.setDraft(v,props.review)})
const formId=computed(()=>'quiz-answer-'+g.value?.id),heading=ref(null)
watch(()=>q.value?.id,async()=>{await nextTick();heading.value?.focus({preventScroll:true})})
watch(()=>!!g.value&&!g.value.done,value=>document.documentElement.classList.toggle('quiz-focus-mode',value),{immediate:true})
let draftTimer
watch(draft,()=>{clearTimeout(draftTimer);draftTimer=setTimeout(()=>store.saveDraft(props.review),700)})
onUnmounted(()=>{clearTimeout(draftTimer);store.saveDraft(props.review);document.documentElement.classList.remove('quiz-focus-mode')})
useStudyActivity(()=>g.value&&!g.value.done?{kind:props.review?'review':'quiz',sessionId:g.value.id}:null)
function submit(){store.submit(props.review)}
</script>
<template><div v-if="g" :class="['panel','study-runner',{'quiz-in-progress':!g.done}]"><p v-if="store.error" class="notice" role="alert">{{store.error}}</p><template v-if="g.done"><div class="result study-result" role="status"><div class="result-origins"><SourceBadge v-for="source in (g.sources??['official'])" :key="source" :source="source"/></div><p class="eyebrow">{{review?'REVIEW COMPLETE':'STUDY COMPLETE'}}</p><h2>{{review?'복습을 마쳤어요!':'오늘도 한 단계 성장했어요!'}}</h2><div class="study-result-score">{{g.result.score}}<small> / 100점</small></div><div class="stats"><span>정답 수 <b>{{g.result.correct}}개</b></span><span>오답 수 <b>{{g.result.wrong}}개</b></span><span>전체 문제 <b>{{g.result.total}}개</b></span></div><p>{{review?'맞힌 문제는 복습 완료로 표시했어요. 최초 정답 보상은 일반 퀴즈와 합쳐 문제당 한 번입니다.':g.result.coins+' 코인 획득! 이미 보상받은 문제는 중복 지급되지 않습니다. 오답은 마이 리틀 펫의 ‘틀린 문제!’에 저장했어요.'}}</p><div class="toolbar"><button @click="store.retry(review)">{{review?'↻ 복습 다시 풀기':'↻ 새 문제로 다시 풀기'}}</button><button class="light" @click="emit(review?'exit':'choose')">{{review?'오답 목록으로':'다른 과목 선택'}}</button><RouterLink v-if="!review" to="/pet/mistakes" class="button light">틀린 문제! →</RouterLink></div></div></template><template v-else-if="q"><div class="runner-topbar"><div class="study-session-heading"><b>{{subjectMap[q.subject].name}}</b><SourceBadge :source="q.source" :creator-name="q.creatorName" :creator-id="q.creatorId" :post-id="q.postId" :version="q.version"/><span>{{typeNames[q.type]}} · {{review?'오답 복습':'퀴즈 타임'}}</span></div><div class="stats"><span>현재 문제 <b>{{g.index+1}} / {{g.questionIds.length}}</b></span><span>진행률 <b>{{Math.round(count/g.questionIds.length*100)}}%</b></span><span>현재 점수 <b>{{Math.round(correct/g.questionIds.length*100)}}점</b></span></div></div><progress :value="count" :max="g.questionIds.length" :aria-label="'제출한 문제 '+count+'개 / '+g.questionIds.length+'개'"/><div class="quiz-workspace"><section :class="['quiz-prompt-pane',{'has-feedback':submitted}]"><p class="eyebrow">QUESTION {{String(g.index+1).padStart(2,'0')}}</p><h2 ref="heading" tabindex="-1" class="study-question">{{q.prompt}}</h2><section v-if="submitted" class="explanation study-feedback" :class="{'feedback-wrong':!submitted.correct}" role="status"><h3>{{submitted.correct?'정답이에요! ✨':'함께 다시 기억해 봐요!'}}</h3><p><b>내 답:</b> {{submitted.answerText}}</p><p><b>정답:</b> {{correctText(q)}}</p><p class="study-explanation">{{q.explanation}}</p><a :href="subjectMap[q.subject].source" target="_blank" rel="noopener noreferrer" class="study-source">공식 학습 문서 ↗</a></section></section><form :id="formId" class="quiz-answer-pane" @submit.prevent="submit"><fieldset v-if="q.type==='multiple'" class="study-options" :disabled="!!submitted||store.busy"><legend class="sr-only">정답을 하나 선택하세요</legend><label v-for="(option,index) in q.options" :key="option.id" :class="['study-option',{selected:draft===option.id,correct:submitted&&option.id===q.correctOptionId,wrong:submitted&&!submitted.correct&&submitted.answer===option.id}]"><input v-model="draft" type="radio" :name="q.id" :value="option.id"/><span class="study-choice-number">{{index+1}}</span><span>{{option.text}}</span></label></fieldset><div v-else class="study-short"><label :for="q.id">답을 입력해 주세요</label><input :id="q.id" v-model="draft" :disabled="!!submitted||store.busy" maxlength="200" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="단어나 짧은 구문을 입력하세요"/><small>양끝 공백과 영문 대소문자는 채점에 영향을 주지 않아요.</small></div></form></div><div class="runner-footer"><div class="study-bottom"><button class="text-button" @click="emit(review?'exit':'choose')">{{review?'← 오답 목록으로':'← 과목·유형 선택으로'}}</button><span>자동 저장 · 시간 제한 없음</span></div><button v-if="!submitted" :form="formId" type="submit" class="study-submit" :disabled="!draft.trim()||store.busy">{{store.busy?'채점 중…':'답안 제출'}}</button><button v-else class="study-next" :disabled="store.busy" @click="store.next(review)">{{g.index===g.questionIds.length-1?'결과 보기':'다음 문제 →'}}</button></div></template></div></template>
